import json

# Pattern spans 3 rows: 4,5,6
# Shift: 5,6,7 would have pattern but 7 is mirror!
# So maybe pattern stops at 6, meaning 4→8s, 5→4, 6→5

input_grid = [
    [5]*20, [5]*20, [5]*20, [5]*20,
    [5, 5, 1, 5, 1, 1, 5] + [5]*13,  # row 4
    [1, 1, 1, 1, 5, 1, 5] + [5]*13,  # row 5
    [5, 5, 1, 1, 1, 1, 1, 5] + [5]*12,  # row 6
    [2]*20,  # row 7 mirror
    [5]*20,  # row 8
]

output = []
for row in range(9):
    if row == 7:
        output.append([2]*20)
    elif row == 8:
        output.append([5]*20)
    elif row == 4:
        output.append([8]*20)  # Top row of pattern → all 8s
    elif row == 5:
        output.append(input_grid[4])  # row 4 pattern shifts here
    elif row == 6:
        output.append(input_grid[5])  # row 5 pattern shifts here
    else:
        output.append([5]*20)

for i, row in enumerate(output):
    val = '8' if row == [8]*20 else ('2' if row == [2]*20 else '1' if any(c == 1 for c in row) else 'empty')
    print(f"Row {i}: {val}")

print("\nSubmit:", json.dumps({"action": "submit", "grid": output}))

